"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[65100],{82599:e=>{e.exports=JSON.parse('{"functions":[{"name":"Equip","desc":"Copies `ServerStorage.WeaponTemplates[weaponName]` into `model`\'s right hand\\nas a Model named `EnemyWeapon` and plays its hold animation (or raises the\\nright arm when it has none). Returns false\\n(and warns once per weapon) if the template, its Handle, or the rig\'s\\nRightHand / RightGripAttachment is missing; nothing is added then.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"weaponName","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":70,"path":"src/ServerStorage/SharedModules/EnemyGear.luau"}},{"name":"PlayAction","desc":"Plays the gun-rig Fire or Reload clip of the body\'s weapon on its Animator (server:\\nthe track replicates). `duration` stretches the clip to last that long. No-op for a\\nweapon without the gun rig or a body without an Animator.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"weaponName","desc":"","lua_type":"string"},{"name":"kind","desc":"","lua_type":"\\"Fire\\" | \\"Reload\\""},{"name":"duration","desc":"","lua_type":"number?"}],"returns":[],"function_type":"static","source":{"line":156,"path":"src/ServerStorage/SharedModules/EnemyGear.luau"}},{"name":"ShowLaser","desc":"Red aim laser from the NPC\'s `Muzzle` (else its root) to `target`. Returns\\nan idempotent cleanup that is safe after `target` is destroyed.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"target","desc":"","lua_type":"BasePart"}],"returns":[{"desc":"","lua_type":"() -> ()\\n"}],"function_type":"static","source":{"line":190,"path":"src/ServerStorage/SharedModules/EnemyGear.luau"}},{"name":"pelletCount","desc":"Casts per shot for a combat profile: `Pellets`, at least 1.","params":[{"name":"profile","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":228,"path":"src/ServerStorage/SharedModules/EnemyGear.luau"}}],"properties":[],"types":[],"name":"EnemyGear","desc":"What an armed NPC visibly carries. `Equip` copies a player weapon from\\n`ServerStorage.WeaponTemplates` into the NPC\'s right hand as a plain\\n`Model` named `EnemyWeapon` (never a `Tool`: a Tool in the workspace can\\nauto-equip), with collision and queries off so it never blocks bullets.\\nThe weapon\'s `Handle.Muzzle` then becomes the shot origin\\n(`EnemyWeapon.MuzzleOrigin`). `ShowLaser` draws the sniper\'s aim warning.\\nA gun-rig weapon (`GunRig.Uses`) hangs from the UpperTorso (`GunJoint`), not the\\nhand. Every armed gun body is tagged `ArmedRig` (its gun carries `Weapon` and\\n`Grip` attributes): every client then runs its aim (and, on the gun rig, its arm\\nIK and recoil) in `AimPoseController`. `PlayAction` plays its Fire / Reload clip.","realm":["Server"],"source":{"line":17,"path":"src/ServerStorage/SharedModules/EnemyGear.luau"}}')}}]);